    static const char *hex = "0123456789abcdef";
    for (size_t i = 0; i < len; ++i) {
        out[i*2] = hex[(in[i] >> 4) & 0xF];
        out[i*2 + 1] = hex[in[i] & 0xF];
    }
    out[len*2] = '\0';
}

static bool authenticate_placeholder(const char *user, const char *pass) {
